function updateSquadScreen(){const names=['能天使','阿米娅','银灰'],roles=['狙击 / 速射手','术师 / 中坚术师','近卫 / 领主'],skills=['过载模式','精神爆发','真银斩'];$('selectedName').textContent=names[op]+' / '+roles[op];$('selectedSkill').textContent='携带技能 · '+skills[op];$('summaryIcon').textContent=['⌖','✧','⚔'][op];document.querySelectorAll('.operator').forEach((button,i)=>{button.setAttribute('aria-pressed',String(i===op))});const stage=MAPS[mapIdx];$('stageCode').textContent='TR-0'+(mapIdx+1);$('stageTitle').textContent=stage.name;$('stageRegion').textContent=mapIdx?'冻原 / 通道防御':'切尔诺伯格 / 外围';const tiles=[];stage.rows.forEach((row,y)=>[...row].forEach((v,x)=>{const fill=v==='#'?'#77909d':v==='R'?'#8b8371':v==='B'?'#75d1ee':'#344953';tiles.push('<rect x="'+(x*12+4)+'" y="'+(y*12+4)+'" width="10" height="10" fill="'+fill+'"/>')}));const start=stage.path[0],goal=stage.path.at(-1);tiles.push('<rect x="'+((start[0]-.5)*12+4)+'" y="'+((start[1]-.5)*12+4)+'" width="10" height="10" fill="#e16c5b"/>');tiles.push('<rect x="'+((goal[0]-.5)*12+4)+'" y="'+((goal[1]-.5)*12+4)+'" width="10" height="10" fill="#6bc9e9"/>');$('stagePreview').innerHTML='<svg viewBox="0 0 248 200" xmlns="http://www.w3.org/2000/svg" aria-label="'+stage.name+'地图预览" role="img">'+tiles.join('')+'</svg>'}
document.querySelectorAll('.operator').forEach(button=>button.addEventListener('click',updateSquadScreen));$('mapBtn').addEventListener('click',updateSquadScreen);updateSquadScreen();
